let sheets, active=0, edits={};
const key='vfw-darts-fall2026-v1', $=id=>document.getElementById(id);
const labels=['Standings','Teams & contacts','Schedule','Match score sheet','Player stats','Bonus points','Scheduling template'];
const descriptions=['The season at a glance. Update weekly results and player records.','Keep team rosters, alternates, and league contacts up to date.','Plan match nights and update home and visiting teams.','Fill out the original five-person match score sheet.','Record wins and losses across each game format.','Track tons, outstanding rounds, and memorable finishes.','Edit the original scheduling worksheet for future planning.'];
const col=n=>{let s='';for(;n;n=Math.floor((n-1)/26))s=String.fromCharCode(65+(n-1)%26)+s;return s};
const colNum=s=>[...s].reduce((a,c)=>a*26+c.charCodeAt(0)-64,0);
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function cell(i,r){return sheets[i].cells.find(c=>c.ref===r)}
function value(i,r){return edits[i]?.[r]??cell(i,r)?.value??''}
function input(i,r,type){const c=cell(i,r);if(c?.formula)return `<span class="calc" title="Original Excel formula; recalculates when opened in Excel">${escape(c.value)} <span class="formula-note">ƒ</span></span>`;let v=value(i,r);type=type||((c?.type==='n'&&v!=='')?'number':'text');if(type==='date'&&v!=='')v=new Date((Number(v)-25569)*86400000).toISOString().slice(0,10);return `<input class="${type==='text'?'text':''}" aria-label="${escape(sheets[i].name+' '+r)}" data-sheet="${i}" data-ref="${r}" type="${type}" ${type==='number'?'step="any"':''} value="${escape(v)}">`}
function save(i,r,v){edits[i]??={};edits[i][r]=v;try{localStorage.setItem(key,JSON.stringify(edits));$('saveStatus').textContent='Draft saved in this browser · '+new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'});}catch{$('saveStatus').textContent='Browser storage unavailable. Export to save your changes.'}updateSummary()}
function updateSummary(){const teams=Array.from({length:6},(_,n)=>{const row=n+6;let w=0,l=0;for(let t=0;t<10;t++){w+=Number(value(0,col(2+t*3)+row))||0;l+=Number(value(0,col(4+t*3)+row))||0}return {name:value(0,'A'+row),w,l}}).sort((a,b)=>b.w-a.w);$('summary').innerHTML=`<div class="stat"><small>TEAMS IN PLAY</small><strong>06</strong><span>A season of friendly competition</span></div><div class="stat"><small>CURRENT LEADER</small><strong style="font-size:22px">${escape(teams[0].name.replace('TEAM ',''))}</strong><span>${teams[0].w} wins · ${teams[0].l} losses</span></div><div class="stat"><small>WORKBOOK</small><strong>07 <span>tabs</span></strong><span>${Object.values(edits).reduce((n,e)=>n+Object.keys(e).length,0)} edited cells in your draft</span></div>`}
function render(){ $('title').textContent=labels[active];$('description').textContent=descriptions[active];$('panelTitle').textContent=active===0?'Week-by-week results':sheets[active].name;$('tabs').innerHTML=labels.map((n,i)=>`<button class="${i===active?'active':''}" data-tab="${i}">${['◈','♙','▦','◎','▥','✧','▤'][i]} &nbsp; ${n}</button>`).join('');$('search').value='';$('hint').textContent=active===0?'Enter wins and losses for each week. Season totals update here as you type. Player records appear below.':'Edit cells directly. Row and column references match Excel. ƒ cells keep the original formulas; Excel recalculates them on opening. Each tab is independent, as in the source workbook.';
 if(active===0){let h='<table><thead><tr><th>TEAM</th>';for(let w=1;w<=10;w++)h+=`<th colspan="2">WEEK ${w} · W / L</th>`;h+='<th>TOTAL W</th><th>TOTAL L</th></tr></thead><tbody>';for(let r=6;r<=11;r++){h+=`<tr><td class="team">${input(0,'A'+r,'text')}</td>`;for(let w=0;w<10;w++)h+=`<td>${input(0,col(2+w*3)+r,'number')}</td><td>${input(0,col(4+w*3)+r,'number')}</td>`;h+=`<td class="calc" data-total-row="${r}" data-side="w"></td><td class="calc" data-total-row="${r}" data-side="l"></td></tr>`}h+='</tbody></table><div style="padding:24px"><h2>Player records</h2><p>Season totals from the standings tab. Update these separately from the bonus log.</p><table><thead><tr><th>PLAYER</th><th>TONS</th><th>POINTS</th><th>ROUNDS</th></tr></thead><tbody>';for(let r=14;r<=31;r++)for(const cs of [['A','E','H','K'],['P','U','X','AA']])if(cell(0,cs[0]+r))h+='<tr>'+cs.map((c,j)=>`<td>${input(0,c+r,j?'number':'text')}</td>`).join('')+'</tr>';h+='</tbody></table></div>';$('content').innerHTML=h;totals();}
 else{const s=sheets[active];let maxR=Math.max(...s.cells.map(c=>Number(c.ref.match(/\d+/)[0]))),maxC=Math.max(...s.cells.map(c=>colNum(c.ref.match(/[A-Z]+/)[0])));if(active===3)maxC=4;if(active===5)maxC=5;let h='<table class="sheet"><thead><tr><th>ROW</th>';for(let c=1;c<=maxC;c++)h+=`<th>${col(c)}</th>`;h+='</tr></thead><tbody>';for(let r=1;r<=maxR;r++){h+=`<tr><td class="row-label">${r}</td>`;for(let c=1;c<=maxC;c++){const ref=col(c)+r;const merged=s.merges.some(m=>{const [a,b]=m.split(':');if(!b)return false;const ac=colNum(a.match(/[A-Z]+/)[0]),bc=colNum(b.match(/[A-Z]+/)[0]),ar=+a.match(/\d+/)[0],br=+b.match(/\d+/)[0];return c>=ac&&c<=bc&&r>=ar&&r<=br&&ref!==a});h+=`<td>${merged?'<span class="empty">—</span>':input(active,ref,(active===2||active===6)&&c===2&&r>1&&Number(value(active,ref))>30000?'date':null)}</td>`}h+='</tr>'}h+='</tbody></table>';$('content').innerHTML=h}updateSummary()}
function totals(){document.querySelectorAll('[data-total-row]').forEach(el=>{let sum=0;for(let w=0;w<10;w++)sum+=Number(value(0,col((el.dataset.side==='w'?2:4)+w*3)+el.dataset.totalRow))||0;el.textContent=sum})}
document.addEventListener('input',e=>{if(e.target.dataset.ref){const i=+e.target.dataset.sheet,r=e.target.dataset.ref;let v=e.target.value;if(e.target.type==='date'&&v)v=String(Date.parse(v)/86400000+25569);save(i,r,v);if(active===0)totals()}});
$('tabs').onclick=e=>{const b=e.target.closest('[data-tab]');if(b){active=+b.dataset.tab;render()}};
$('search').oninput=e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('#content tbody tr').forEach(tr=>{const t=tr.textContent+' '+[...tr.querySelectorAll('input')].map(i=>i.value).join(' ');tr.hidden=!t.toLowerCase().includes(q)})};
$('reset').onclick=()=>{if(confirm('Discard all draft changes and restore the supplied Week 7 workbook?')){edits={};localStorage.removeItem(key);render();$('saveStatus').textContent='Restored the original Week 7 workbook'}};
// Patch only changed cells in the original OOXML package so Excel-only formatting and print settings survive.
function patchWorkbook(bytes,changes){const files=fflate.unzipSync(bytes),decoder=new TextDecoder(),encoder=new TextEncoder(),parser=new DOMParser(),serial=new XMLSerializer(),ns='http://schemas.openxmlformats.org/spreadsheetml/2006/main';for(const [i,changesForSheet] of Object.entries(changes)){const path=sheets[i].path,doc=parser.parseFromString(decoder.decode(files[path]),'application/xml'),data=doc.getElementsByTagNameNS(ns,'sheetData')[0];for(const [ref,v] of Object.entries(changesForSheet)){if(cell(+i,ref)?.formula)continue;const rn=+ref.match(/\d+/)[0],cn=colNum(ref.match(/[A-Z]+/)[0]);let row=[...data.children].find(e=>+e.getAttribute('r')===rn);if(!row){row=doc.createElementNS(ns,'row');row.setAttribute('r',rn);data.insertBefore(row,[...data.children].find(e=>+e.getAttribute('r')>rn)||null)}let c=[...row.children].find(e=>e.getAttribute('r')===ref);if(!c){c=doc.createElementNS(ns,'c');c.setAttribute('r',ref);row.insertBefore(c,[...row.children].find(e=>colNum(e.getAttribute('r').match(/[A-Z]+/)[0])>cn)||null)}while(c.firstChild)c.removeChild(c.firstChild);c.removeAttribute('t');if(v!==''){if(cell(+i,ref)?.type!=='s'&&Number.isFinite(Number(v))){const vv=doc.createElementNS(ns,'v');vv.textContent=String(Number(v));c.appendChild(vv)}else{c.setAttribute('t','inlineStr');const is=doc.createElementNS(ns,'is'),t=doc.createElementNS(ns,'t');t.setAttribute('xml:space','preserve');t.textContent=v;is.appendChild(t);c.appendChild(is)}}}files[path]=encoder.encode(serial.serializeToString(doc))}
const wb=parser.parseFromString(decoder.decode(files['xl/workbook.xml']),'application/xml');let calc=wb.getElementsByTagNameNS(ns,'calcPr')[0];if(!calc){calc=wb.createElementNS(ns,'calcPr');wb.documentElement.appendChild(calc)}calc.setAttribute('fullCalcOnLoad','1');calc.setAttribute('forceFullCalc','1');calc.setAttribute('calcMode','auto');files['xl/workbook.xml']=encoder.encode(serial.serializeToString(wb));return fflate.zipSync(files)}
$('export').onclick=async()=>{const b=$('export');b.disabled=true;b.textContent='Preparing workbook…';$('message').textContent='';try{const res=await fetch('template.xlsx');if(!res.ok)throw Error('Template could not be loaded');const bytes=patchWorkbook(new Uint8Array(await res.arrayBuffer()),edits),url=URL.createObjectURL(new Blob([bytes],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'})),a=document.createElement('a');a.href=url;a.download='VFW DARTS FALL 2026 - UPDATED.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);$('saveStatus').textContent='Workbook exported · formulas recalculate in Excel'}catch(e){$('message').textContent='Export failed: '+e.message}finally{b.disabled=false;b.textContent='↓  Export Excel'}};
fetch('workbook.json').then(r=>{if(!r.ok)throw Error('Workbook data unavailable');return r.json()}).then(data=>{sheets=data;try{edits=JSON.parse(localStorage.getItem(key)||'{}')}catch{edits={}}render()}).catch(e=>$('message').textContent=e.message);
